/*
 * Identify transcripts with homer
 */

include { UNZIP                  } from 'nf-core/unzip'

include { HOMER_MAKETAGDIRECTORY } from 'nf-core/homer/maketagdirectory'
include { HOMER_MAKEUCSCFILE     } from 'nf-core/homer/makeucscfile'
include { HOMER_FINDPEAKS        } from 'nf-core/homer/findpeaks'
include { HOMER_POS2BED          } from 'nf-core/homer/pos2bed'

workflow HOMER_GROSEQ {
    take:
    bam     // channel: [ val(meta), [ reads ] ]
    fasta   //    file: /path/to/bwa/index/
    uniqmap

    main:

    ch_uniqmap = channel.empty()

    if (!uniqmap) {
        ch_uniqmap = []
    }
    else if (uniqmap.endsWith('.zip')) {
        ch_uniqmap = UNZIP([[:], uniqmap]).unzipped_archive.map { index -> index[1] }
    }
    else {
        ch_uniqmap = uniqmap
    }

    /*
    * Create a Tag Directory From The GRO-Seq experiment
    */
    HOMER_MAKETAGDIRECTORY(bam, fasta)

    /*
    * Creating UCSC Visualization Files
    */
    HOMER_MAKEUCSCFILE(HOMER_MAKETAGDIRECTORY.out.tagdir)

    /*
    * Find transcripts directly from GRO-Seq
    */
    HOMER_FINDPEAKS(HOMER_MAKETAGDIRECTORY.out.tagdir, ch_uniqmap)

    /*
    * Convert peak file to bed file
    */
    HOMER_POS2BED(HOMER_FINDPEAKS.out.txt)

    emit:
    tagdir    = HOMER_MAKETAGDIRECTORY.out.tagdir // channel: [ val(meta), [ tagdir ] ]
    bed_graph = HOMER_MAKEUCSCFILE.out.bedGraph // channel: [ val(meta), [ tag_dir/*ucsc.bedGraph.gz ] ]
    peaks     = HOMER_FINDPEAKS.out.txt // channel: [ val(meta), [ *peaks.txt ] ]
    bed       = HOMER_POS2BED.out.bed // channel: [ val(meta), [ *peaks.txt ] ]
}

nextflow_workflow {

    name "Test Workflow HOMER_GROSEQ"
    script "../main.nf"
    workflow "HOMER_GROSEQ"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/homer_groseq"
    tag "homer"
    tag "unzip"
    tag "homer/maketagdirectory"
    tag "homer/makeucscfile"
    tag "homer/findpeaks"
    tag "homer/pos2bed"

    test("Should run HOMER_GROSEQ with BAM input") {

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    path(workflow.out.bed_graph.get(0).get(1)).linesGzip.size(),
                    sanitizeOutput(workflow.out, unstableKeys:["bed_graph"])
                ).match() },
            )
        }
    }

    test("Should run HOMER_GROSEQ with BED input") {
        config "./bed.config"

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/bed/test.bed', checkIfExists: true),
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    path(workflow.out.bed_graph.get(0).get(1)).linesGzip.size(),
                    sanitizeOutput(workflow.out, unstableKeys:["bed_graph"])
                ).match() }
            )
        }
    }

    test("Test files from GROseq tutorial with uniqmap") {

        tag "uniqmap"

        config "./bed.config"

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'test' ],
                    [file('ftp://ftp.ncbi.nlm.nih.gov/geo/samples/GSM340nnn/GSM340901/suppl/GSM340901_lib1_aligned.bed.gz', checkIfExists: true),
                    file('ftp://ftp.ncbi.nlm.nih.gov/geo/samples/GSM340nnn/GSM340902/suppl/GSM340902_lib2_aligned.bed.gz', checkIfExists: true)],
                ]
                input[1] = file('https://hgdownload.soe.ucsc.edu/goldenPath/hg18/chromosomes/chr14.fa.gz', checkIfExists: true)
                input[2] = file('https://raw.githubusercontent.com/nf-core/test-datasets/nascent/reference/uniqmap.GRCh38_chr21.50nt.zip', checkIfExists: true)
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    path(workflow.out.bed_graph.get(0).get(1)).linesGzip.size(),
                    sanitizeOutput(workflow.out, unstableKeys:["bed_graph"])
                ).match() }
            )
        }
    }

    test("sarscov2 - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = [
                    [ id: 'test' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true),
                ]
                input[1] = file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out)).match() }
            )
        }
    }
}

